const base=`http://127.0.0.1:${server.address().port}`;
async function request(route,user,method='GET',body){const res=await fetch(base+'/api'+route,{method,headers:{'x-demo-user':user,'x-demo-name':encodeURIComponent(user==='demo-player-0001'?'Роман':'Вика'),'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});return {status:res.status,data:await res.json()};}
const registration=(name,gender,role='player')=>({name:name.includes(' ')?name:name+' Тестов',gender,role,phone:'+7 999 123-45-67',telegramContact:role==='coach'?'coach_test':null,playingYears:2,ntrpLevel:role==='coach'?null:3.5,about:role==='coach'?'Веду занятия по теннису':'Играю по выходным',coachYears:role==='coach'?1:null,avatarId:gender==='female'?'female-serve':'male-cap',photoData:null});
const coachPhoto='data:image/jpeg;base64,'+Buffer.from([0xff,0xd8,0xff,0xd9]).toString('base64');
