 assert.equal((await request('/profile',owner,'POST',{...registration('Ищу тренировку','female'),city:'Краснодар'})).status,200);
 assert.equal((await request('/profile',coach,'POST',{...registration('Тренер','male','coach'),city:'Краснодар',coachSports:['tennis']})).status,200);
 assert.equal((await request('/profile',player,'POST',{...registration('Партнёр','male'),city:'Краснодар'})).status,200);
 assert.equal((await request('/profile',padelOnly,'POST',{...registration('Только падел','male'),city:'Краснодар'})).status,200);
